en_arb_path = os.path.join(l10n_dir, 'app_en.arb')
with open(en_arb_path, 'r', encoding='utf-8') as f:
    en_arb = json.load(f)

for lang in langs:
    arb_path = os.path.join(l10n_dir, f'app_{lang}.arb')
    
    # load or create new arb
    if os.path.exists(arb_path):
        with open(arb_path, 'r', encoding='utf-8') as f:
            lang_arb = json.load(f)
    else:
        lang_arb = {"@@locale": lang}
        
    for key, en_val in en_arb.items():
        if key == "@@locale" or key.startswith("@"):
            if key not in lang_arb:
                lang_arb[key] = en_val
            continue
            
        # Do we have a custom translation?
        if key in trans and lang in trans[key]:
            lang_arb[key] = trans[key][lang]
        else:
            # maintain existing translated value unless it is missing
            if key not in lang_arb:
                # fall back to english if missing in trans script (which shouldn't happen for the new ones)
                lang_arb[key] = en_val
                
    # write out string
    with open(arb_path, 'w', encoding='utf-8') as f:
        json.dump(lang_arb, f, ensure_ascii=False, indent=2)

print("Updated ARB files!")
